const r = await tools.exec_command({cmd:"python - <<'PY'
import pandas as pd,glob
m=pd.read_csv('/app/dataset/sensor_metadata.csv').set_index('sensor_id')
xs=[]
for f in glob.glob('/app/dataset/sensors_*.csv'):
 d=pd.read_csv(f);d['lt']=pd.to_datetime(d.timestamp);d=d.join(m,on='sensor_id');d['pt']=d.lt-pd.to_timedelta(d.logger_utc_offset_hours,unit='h')-pd.to_timedelta(d.response_delay_minutes,unit='m');xs.append(d)
df=pd.concat(xs)
for sub,g0 in df.groupby('subsystem'):
 print('\n###',sub)
 for sid,g in g0.groupby('sensor_id'):
  g=g.sort_values('pt').set_index('pt')
  base=g.loc[:'2024-01-15 23:59','value'].median()
  q=g.loc['2024-01-16 00:00':'2024-01-16 02:00','value'].resample('5min').mean()
  # group by every 10 mins, deviations from base
  vals=[]
  for t,v in q.items():
   if t.minute%10==0: vals.append(f'{t:%H:%M}{v-base:+.3f}')
  print(f'{sid:18s} base={base:.4f}: '+ ' '.join(vals))
PY",workdir:"/app",yield_time_ms:10000,max_output_tokens:9500}); text(r.output);

